class LegacyOrder(BaseModel):
    model_config = ConfigDict(extra="ignore")     # tolerate upstream additions
    order_id: str
    qty: int = Field(gt=0)                        # validated at the seam

    @field_validator("order_id")
    @classmethod
    def non_empty(cls, v: str) -> str: return v.strip()

def to_domain(payload: bytes) -> Order:
    legacy = LegacyOrder.model_validate_json(payload)   # parse, don't trust
    return Order(id=legacy.order_id, quantity=legacy.qty)
